            family: string;
            /** @description `base` restabelece o texto inteiro e aposenta o base anterior com as emendas dele; `amendment` altera o base em vigor e só contém o que mudou. */
            role: string;
            /** @description Posição por data de protocolo na fila INTEIRA, base e emendas juntas. 1 = o mais antigo. */
            index: number;
            /** @description Quantos documentos há na fila, incluindo os sem data. */
            total: number;
            /** @description `true` quando este documento, sozinho, é o texto em vigor: o último `base` sem emenda posterior. `false` quando foi substituído, quando há emendas depois dele (`amendments_after`) ou quando é uma emenda. `null` quando há documento sem data na fila ou nenhum `base` a que somar as emendas. */
            is_current: boolean | null;
            /** @description Protocolo do `base` em vigor — o documento a que as emendas de `amendments_after` se somam. Nulo quando a fila não tem base nenhum. */
            current_base: string | null;
            /** @description Protocolos que alteram `current_base`, do mais antigo ao mais recente. Lista vazia é medição, não omissão: o base em vigor não recebeu emenda. É este campo que separa "leia este documento" de "leia este documento MAIS estes três". */
            amendments_after: string[];
            /** @description Este é o último elo datado da fila. Afirmação do servidor, para não obrigar a derivá-la de `next_in_chain == null` com `index == total`. Falso quando há documento sem data, porque aí não há último. */
            is_latest_in_chain: boolean;
            /** @description Documentos da fila sem data de protocolo, excluídos da ordenação para não decidir o vigente por posição arbitrária. */
            undated: number;
            /** @description Documentos da fila que EXISTEM no acervo e ainda não foram lidos: contam para a ordem e para a vigência, mas `readDocument` ainda não os recupera. "Não existe" e "existe e ainda não foi processado" são a mesma ausência com significados opostos. */
            unindexed: number;
