    searchDocuments: {
        parameters: {
            query: {
                /** @description Termo/pergunta em linguagem natural. */
                q: string;
                /** @description Filtra por papéis, ex.: PETR4,PRIO3. */
                tickers?: string[];
                /** @description Categoria bruta, sensível ao rótulo exato da fonte. Descubra em getDocumentTaxonomy; prefira document_kind quando possível. */
                category?: string;
                /** @description Taxonomia estável do DataBolsa. Para crédito: debt_instrument reúne escrituras, termos de securitização e aditamentos; governing_document reúne regulamentos/documentos constitutivos. */
                document_kind?: components["schemas"]["DocumentKind"];
                /** @description Que tipo de entidade o documento descreve. `issuer` é a companhia registrada apenas para emitir dívida (concessionária, SPE): publica demonstrações e documentos, e não tem ticker. `securitization` é o certificado (CRI/CRA/OTS), identificado pelo ISIN e não pela securitizadora. */
                entity_type?: components["schemas"]["DocumentEntityType"];
                /** @description CNPJ do emissor (14 dígitos; pontuação é aceita e ignorada). É a chave de entidade para documentos de crédito, que não têm ticker. */
                issuer_cnpj?: string;
                /** @description Identificador do papel: ISIN, código ANBIMA da debênture ou código de instrumento da B3 — qualquer um dos que a emissão carrega. */
                asset_code?: string;
                /** @description Família do papel; eixo independente de entity_type. */
                asset_family?: "DEB" | "CRI" | "CRA" | "OTS" | "FIDC" | "FIAGRO";
                /** @description Ano de referência do documento (AAAA). */
                year?: number;
                /** @description Inclui apenas documentos protocolados até a data. Exclui itens sem `filed_at` conhecido e sinaliza isso em `warnings`; não confundir com o período de referência. */
                filed_before?: string;
                /** @description Só documentos protocolados (filed_at) a partir desta data. Documentos sem data de publicação são excluídos. */
                filed_after?: string;
                /** @description Restringe a UM documento exato (protocolo CVM/FNET) — busca dentro do documento. */
                protocol?: string;
                /** @description Período de referência exato do documento (ex.: 2022-06-30 = 2T22). */
                reference_date?: string;
                /** @description Início do intervalo de reference_date (inclusivo). */
                reference_from?: string;
                /** @description Fim do intervalo de reference_date (inclusivo). */
                reference_to?: string;
                /** @description Subtipo bruto, sensível ao rótulo exato da fonte (ex.: Relatório de Agência de Rating). Descubra em getDocumentTaxonomy. */
                doc_type?: string;
                /** @description Restringe a trechos de tabela (fatos numéricos). */
                tables_only?: boolean;
                /** @description Restringe a emissores financeiros quando true; false restringe aos demais. */
                financial_only?: boolean;
                /** @description false remove o bloco duplicado meta.context e reduz tokens; data[].text/text_expanded e citation continuam completos. Em clientes MCP, prefira false salvo quando precisar de contexto pronto para colar em outro prompt. */
                include_context?: boolean;
                /** @description Máximo de trechos (1–25, default 8). */
                limit?: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Trechos relevantes + bloco de contexto com citação. */
            200: {
                headers: {
                    /** @description Segundos até o reinício da janela. */
                    "Retry-After"?: number;
                    "RateLimit-Limit"?: number;
                    "RateLimit-Remaining"?: number;
                    /** @description Segundos até o reinício da janela. */
                    "RateLimit-Reset"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["DocumentSearchResponse"];
                };
            };
            /** @description Limite diário de requisições do plano atingido. */
            429: {
                headers: {
                    /** @description Segundos até o reinício da janela. */
                    "Retry-After"?: number;
                    "RateLimit-Limit"?: number;
                    "RateLimit-Remaining"?: number;
                    /** @description Segundos até o reinício da janela. */
                    "RateLimit-Reset"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description Erro (RFC 9457 application/problem+json) */
            default: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
